import assert from 'node:assert/strict';
import { performance } from 'node:perf_hooks';
import { writeFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { contains } from './linear.mjs';
import { createLookup } from './indexed.mjs';

// A parent process enforces the limit even if synchronous benchmark work stalls.
if (!process.argv.includes('--worker')) {
  const run = spawnSync(process.execPath, [fileURLToPath(import.meta.url), '--worker'], {
    timeout: 30_000, encoding: 'utf8', cwd: process.cwd(),
  });
  if (run.error) throw run.error;
  if (run.status !== 0) throw new Error(run.stderr || `Benchmark exit ${run.status}`);
  const report = JSON.parse(run.stdout);
  writeFileSync(new URL('./results.json', import.meta.url), JSON.stringify(report, null, 2) + '\n');
  process.stdout.write(run.stdout);
} else {
  const datasetSize = 1000;
  const queryCount = 500;
  const repetitions = 3;
  const expectedMatches = 334;
  const labels = Array.from({ length: datasetSize }, (_, n) => `L${n}`);
  const queries = Array.from({ length: queryCount }, (_, n) => `L${n * 3}`);
  const expected = queries.map((_, n) => n * 3 < datasetSize);
  assert.equal(expected.filter(Boolean).length, expectedMatches);
  const results = [];
  let baseline;
  for (const name of ['linear', 'indexed']) {
    const buildStart = performance.now();
    const lookup = name === 'linear' ? query => contains(labels, query) : createLookup(labels);
    const buildMs = performance.now() - buildStart;
    const queryMs = [];
    const matches = [];
    for (let batch = 0; batch < repetitions; batch++) {
      const start = performance.now();
      const answers = queries.map(lookup);
      queryMs.push(performance.now() - start);
      assert.deepEqual(answers, expected);
      if (baseline) assert.deepEqual(answers, baseline);
      else baseline = answers;
      matches.push(answers.filter(Boolean).length);
      assert.equal(matches.at(-1), expectedMatches);
    }
    assert.ok([buildMs, ...queryMs].every(ms => Number.isFinite(ms) && ms >= 0));
    results.push({ name, buildMs, queryMs, matches });
  }
  process.stdout.write(JSON.stringify({
    datasetSize, queryCount, repetitions, expectedMatches,
    runtime: process.version, platform: process.platform, architecture: process.arch,
    measuredAt: new Date().toISOString(), units: 'milliseconds',
    method: 'performance.now; build once; three query batches; no warmup; linear then indexed; assertions outside timed regions',
    correctness: 'All 500 answers per batch equal expected membership and each other',
    results,
  }, null, 2) + '\n');
}

